#!/usr/bin/env bash
# Optional: writes an empty Config/Secrets.xcconfig so INFOPLIST_KEY_* resolve.
# The app does not read baked URL/token from Info.plist — login sets the server; JWT is in Keychain.
# Kept for local Xcode builds that still reference Secrets.xcconfig via Debug/Release.xcconfig.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$ROOT/Config/Secrets.xcconfig"

cat > "$OUT" <<'EOF'
// Generated by scripts/sync-secrets-xcconfig.sh — empty on purpose
SLASH = /
KBAPP_API_BASE_URL =
KBAPP_AUTH_TOKEN =
INFOPLIST_KEY_KBAppAPIBaseURL = $(KBAPP_API_BASE_URL)
INFOPLIST_KEY_KBAppAuthToken = $(KBAPP_AUTH_TOKEN)
EOF

echo "Wrote empty $OUT (runtime config comes from onboarding + Keychain)"
